export function Ssr({
  pageTitle = "{{pageTitle}}",
  stage = "{{stage}}",
  accent = "{{accent}}",
  showTimes = {{showTimes}},
}) {
  const steps = [
    { id: "requesting", label: "Browser requests page", time: "0ms" },
    { id: "rendering", label: "Server fetches data + renders HTML", time: "~180ms" },
    { id: "delivered", label: "Full HTML delivered", time: "~200ms" },
  ];
  const previews = { requesting: "\u00A0", rendering: "\u25F0", delivered: "Full page content" };
  return (
    <div role="img" aria-label={`SSR for ${pageTitle}, stage ${stage}`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 320, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>{pageTitle}</p>
      <div style={{ display: "flex", gap: 6, marginBottom: 14 }}>
        {steps.map((s) => (
          <span key={s.id} style={{ flex: 1, textAlign: "center", padding: "8px 4px", borderRadius: 8, fontSize: 10, fontWeight: 600, opacity: s.id === stage ? 1 : .4, background: s.id === stage ? accent : "#24143010" }}>
            {s.label}
            {showTimes && <small style={{ display: "block", fontWeight: 400, color: "#24143099", marginTop: 3 }}>{s.time}</small>}
          </span>
        ))}
      </div>
      <div style={{ height: 56, display: "grid", placeItems: "center", background: "#ffffff", border: "1.5px dashed #24143020", borderRadius: 8, fontSize: 20, fontWeight: 700, color: stage === "delivered" ? accent : "#241430" }}>{previews[stage]}</div>
    </div>
  );
}
